import java.io.*;
import java.util.*;

public class Solution {
    static class InputStreamReaderWrapper {
        BufferedReader reader;
        StringTokenizer tokenizer;

        InputStreamReaderWrapper() {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = null;
        }

        String getNextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    System.out.println(e);
                }
            }
            return tokenizer.nextToken();
        }

        int getNextInt() {
            return Integer.parseInt(getNextToken());
        }

        long getNextLong() {
            return Long.parseLong(getNextToken());
        }

        double getNextDouble() {
            return Double.parseDouble(getNextToken());
        }

        String getNextLine() {
            try {
                if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    tokenizer = new StringTokenizer(reader.readLine());
                }
            } catch (IOException e) {
                System.out.println(e);
            }
            return tokenizer.nextToken("\n");
        }
    }

    static final long MOD = 998244353L;
    static final int MAXN = 200005;
    static long[] factorialsArr = new long[MAXN];

    static long fastPower(long base, long exp, long mod) {
        long result = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long nChooseK(int n, int k) {
        if (k > n) return 0L;
        return factorialsArr[n] * fastPower(factorialsArr[k], MOD - 2, MOD) % MOD * fastPower(factorialsArr[n - k], MOD - 2, MOD) % MOD;
    }

    static long sumCalculation(int n, int k) {
        long totalSum = 0;
        for (int i = 0; i <= n - k; i++) {
            long val = nChooseK(n - k, i) * fastPower(n - k - i, n, MOD) % MOD;
            if (i % 2 == 0) totalSum = (totalSum + val) % MOD;
            else totalSum = (totalSum - val + MOD) % MOD;
        }
        return totalSum;
    }

    public static void main(String[] args) {
        InputStreamReaderWrapper input = new InputStreamReaderWrapper();
        int t = 1;
        // t = input.getNextInt();
        for (int q = 0; q < t; q++) {
            long n = input.getNextLong();
            long k = input.getNextLong();
            factorialsArr[0] = 1;
            for (long i = 1; i <= n; i++) {
                factorialsArr[(int) i] = factorialsArr[(int) (i - 1)] * i % MOD;
            }
            if (k >= n) {
                System.out.println(0);
            } else if (k == 0) {
                System.out.println(factorialsArr[(int) n]);
            } else {
                long res = 2 * nChooseK((int) n, (int) (n - k)) * sumCalculation((int) n, (int) k) % MOD;
                System.out.println(res);
            }
        }
    }
}
