#include <bits/stdc++.h>
using namespace std;

struct InputStreamReaderWrapper {
    std::istringstream tokenizer;
    std::string currentLine;

    void readNextLine() {
        std::getline(std::cin, currentLine);
        tokenizer.clear();
        tokenizer.str(currentLine);
    }

    std::string getNextToken() {
        while (!(tokenizer >> std::ws)) {
            readNextLine();
        }
        std::string token;
        tokenizer >> token;
        return token;
    }

    int getNextInt() {
        return std::stoi(getNextToken());
    }

    long long getNextLong() {
        return std::stoll(getNextToken());
    }

    double getNextDouble() {
        return std::stod(getNextToken());
    }

    std::string getNextLine() {
        readNextLine();
        return currentLine;
    }
};

